from collections import deque

def zero_components(grid):
    H,W=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
       if grid[r][c]==0 and (r,c) not in seen:
        q=[(r,c)];seen.add((r,c)); comp=[]
        for x,y in q:
         comp.append((x,y))
         for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
          if 0<=a<H and 0<=b<W and grid[a][b]==0 and (a,b) not in seen:
           seen.add((a,b));q.append((a,b))
        comps.append(comp)
    return sorted(comps,key=len,reverse=True)
